import Foundation

enum Route {
    case home
    case product(Int)
    case unknown
}

func parse(url: URL) -> Route {
    let parts = url.pathComponents.filter { $0 != "/" }
    if parts.count >= 2, parts[0] == "items", let id = Int(parts[1]) {
        return .product(id)
    }
    return .unknown
}

let sample = URL(string: "https://example.com/items/77")!
let route = parse(url: sample)
switch route {
case .product(let id):
    print("Item: \(id)")
default:
    print("Other")
}

import Foundation

func getQueryValue(url: URL, name: String) -> String? {
    let comps = URLComponents(url: url, resolvingAgainstBaseURL: false)
    return comps?.queryItems?.first(where: { $0.name == name })?.value
}

let link = URL(string: "myapp://invite?code=VIP2026")!
let code = getQueryValue(url: link, name: "code")
print("Invite: \(code ?? "none")")

