import Foundation

enum SchemeSafety {
    case secureVerified
    case unverifiedCustom
}

func evaluate(scheme: String) -> SchemeSafety {
    if scheme == "https" {
        return .secureVerified
    }
    return .unverifiedCustom
}

print("Safety: \(evaluate(scheme: "myapp"))")

import Foundation

class DeepLinkQueue {
    var pendingURLs: [URL] = []

    func enqueue(url: URL) {
        pendingURLs.append(url)
    }

    func popPending() -> URL? {
        if pendingURLs.isEmpty {
            return nil
        }
        return pendingURLs.removeFirst()
    }

    var count: Int {
        pendingURLs.count
    }
}

let queue = DeepLinkQueue()
queue.enqueue(url: URL(string: "https://example.com/account")!)
print("Pending: \(queue.count)")

