import Foundation

enum AppRoute: Equatable {
    case home
    case profile(id: Int)
    case unknown

    static func parse(url: URL) -> AppRoute {
        let parts = url.pathComponents.filter { $0 != "/" }
        if parts.isEmpty {
            return .home
        }
        if parts.first == "users", parts.count > 1, let id = Int(parts[1]) {
            return .profile(id: id)
        }
        return .unknown
    }
}

let parsed = AppRoute.parse(url: URL(string: "https://example.com/users/42")!)
print("Parsed: \(parsed)")

