import Foundation

struct UniversalLinkValidator {
    let allowedHost: String

    func isValid(url: URL) -> Bool {
        if let scheme = url.scheme?.lowercased(), scheme == "https" {
            return url.host?.lowercased() == allowedHost.lowercased()
        }
        return false
    }
}

let validator = UniversalLinkValidator(allowedHost: "example.com")
let testURL = URL(string: "https://example.com/feed")!
print("Valid: \(validator.isValid(url: testURL))")

