import Foundation

class DeepLinkBuffer {
    var storedURL: URL?

    func store(url: URL) {
        storedURL = url
    }

    func retrieveAndClear() -> URL? {
        let url = storedURL
        storedURL = nil
        return url
    }
}

let buffer = DeepLinkBuffer()
buffer.store(url: URL(string: "https://example.com/dashboard")!)
let retrieved = buffer.retrieveAndClear()
print("Retrieved: \(retrieved?.absoluteString ?? "none")")
